// Some portions generated by Claude
import assert from "node:assert/strict";
import test from "node:test";
import {canvasGraph, RDF_TYPE} from "../../../main/frontend/graph-explorer/graph-canvas-scope.ts";

const iri = (id, extra = {}) => ({id, label: id.slice(4), kind: "iri", ...extra});
const literal = (id) => ({id, label: id, kind: "literal"});
const edge = (source, predicate, target) => ({id: `${source} ${predicate} ${target}`, source, predicate, label: predicate, target});

// alice knows bob, works for acme, has a name and an age, and is a Person; Person has no triples of its own.
const graph = {
  revision: 7,
  nodes: [
    iri("urn:alice"), iri("urn:bob"), iri("urn:acme"), iri("urn:Person"), iri("urn:Thing"),
    literal('"Alice"'), literal('"39"'), {id: "_:b1", label: "b1", kind: "blank"},
  ],
  edges: [
    edge("urn:alice", "urn:knows", "urn:bob"),
    edge("urn:alice", "urn:worksFor", "urn:acme"),
    edge("urn:alice", "urn:name", '"Alice"'),
    edge("urn:alice", "urn:age", '"39"'),
    edge("urn:alice", RDF_TYPE, "urn:Person"),
    edge("urn:bob", RDF_TYPE, "urn:Person"),
    edge("urn:bob", RDF_TYPE, "urn:Thing"),
    edge("urn:Thing", "urn:name", '"Alice"'),
    edge("urn:acme", "urn:address", "_:b1"),
  ],
};

test("with values shown the canvas draws the graph itself", () => {
  assert.equal(canvasGraph(graph, true), graph);
});

test("without values the canvas draws resources and the links between them", () => {
  const drawn = canvasGraph(graph, false);
  assert.equal(drawn.revision, graph.revision);
  assert.deepEqual(drawn.nodes.map((node) => node.id), ["urn:alice", "urn:bob", "urn:acme", "_:b1"]);
  assert.deepEqual(drawn.edges.map((candidate) => candidate.id), [
    "urn:alice urn:knows urn:bob",
    "urn:alice urn:worksFor urn:acme",
    "urn:acme urn:address _:b1",
  ]);
});

test("kept nodes are the model's own objects, so positions written to the model reach the canvas", () => {
  const drawn = canvasGraph(graph, false);
  assert.equal(drawn.nodes[0], graph.nodes[0]);
  assert.equal(drawn.edges[0], graph.edges[0]);
});

test("a class stays on the canvas when something other than rdf:type links it", () => {
  const linked = {...graph, edges: [...graph.edges, edge("urn:acme", "urn:hires", "urn:Person")]};
  const drawn = canvasGraph(linked, false);
  assert.ok(drawn.nodes.some((node) => node.id === "urn:Person"));
  assert.ok(!drawn.edges.some((candidate) => candidate.predicate === RDF_TYPE));
});

test("resources without links, such as a search hit with only literal values, stay on the canvas", () => {
  const lonely = {revision: 1, nodes: [iri("urn:solo"), literal('"Solo"')], edges: [edge("urn:solo", "urn:name", '"Solo"')]};
  assert.deepEqual(canvasGraph(lonely, false).nodes.map((node) => node.id), ["urn:solo"]);
});

const RDFS_LABEL = "http://www.w3.org/2000/01/rdf-schema#label";
const SKOS_ALT = "http://www.w3.org/2004/02/skos/core#altLabel";
const titled = {
  revision: 3,
  nodes: [
    iri("urn:oslo", {label: "Oslo"}), iri("urn:bergen", {label: "Bergen"}), iri("urn:norway", {label: "Norway"}),
    {id: '"Oslo"', label: "Oslo", kind: "literal"}, {id: '"Kristiania"', label: "Kristiania", kind: "literal"},
    {id: '"Bergen"', label: "Bergen", kind: "literal"}, {id: '"700000"', label: "700000", kind: "literal"},
  ],
  edges: [
    edge("urn:oslo", RDFS_LABEL, '"Oslo"'),
    edge("urn:oslo", SKOS_ALT, '"Kristiania"'),
    edge("urn:oslo", "urn:population", '"700000"'),
    edge("urn:bergen", RDFS_LABEL, '"Bergen"'),
    edge("urn:norway", "urn:motto", '"Bergen"'),
    edge("urn:oslo", "urn:in", "urn:norway"),
  ],
};

test("with values shown, a label value that repeats its card's title is not drawn again", () => {
  const drawn = canvasGraph(titled, true);
  assert.ok(!drawn.nodes.some((node) => node.id === '"Oslo"'), "the title of Oslo is its card");
  assert.ok(!drawn.edges.some((candidate) => candidate.id === `urn:oslo ${RDFS_LABEL} "Oslo"`));
  assert.ok(drawn.nodes.some((node) => node.id === '"Kristiania"'), "a label that differs from the title is a value");
  assert.ok(drawn.nodes.some((node) => node.id === '"700000"'));
  // "Bergen" is also Norway's motto, so it is a value of its own: the card and both links stay.
  assert.ok(drawn.nodes.some((node) => node.id === '"Bergen"'));
  assert.equal(drawn.edges.length, titled.edges.length - 1);
  assert.equal(drawn.revision, titled.revision);
  assert.equal(canvasGraph(titled, true), drawn, "the drawn graph of a graph is computed once");
});
